begin;
\ir fixtures/clinical.sql
reset role;
update public.locations set timezone='America/New_York'where id=pg_temp.location();
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,state,created_by,checked_in_at,started_at,completed_at)
select pg_temp.id(10000+n),pg_temp.practice(),pg_temp.id(1),pg_temp.location(),pg_temp.patient(),'2026-01-01T05:00:00Z'::timestamptz+make_interval(mins=>n*15),'2026-01-01T05:05:00Z'::timestamptz+make_interval(mins=>n*15),'America/New_York','Synthetic report clinic',s.state,pg_temp.id(1),case when s.state in('checked_in','in_progress','completed')then '2026-01-01T05:00:00Z'::timestamptz+make_interval(mins=>n*15)end,case when s.state in('in_progress','completed')then '2026-01-01T05:01:00Z'::timestamptz+make_interval(mins=>n*15)end,case when s.state='completed'then '2026-01-01T05:04:00Z'::timestamptz+make_interval(mins=>n*15)end from generate_series(0,39)n cross join lateral(select case when n%6=2 and n<>2 then 'booked'else(array['booked','checked_in','in_progress','completed','cancelled','no_show'])[1+n%6]end state)s;
insert into public.appointments(id,practice_id,doctor_user_id,location_id,patient_id,starts_at,ends_at,timezone,location_name,state,created_by,checked_in_at,started_at,completed_at)
select pg_temp.id(n),pg_temp.practice(),pg_temp.id(1),pg_temp.location(),pg_temp.patient(),starts,starts+interval'5 minutes','America/New_York','Synthetic report clinic','completed',pg_temp.id(1),starts,starts+interval'1 minute',starts+interval'4 minutes'from(values(10100,'2026-01-01T04:55:00Z'::timestamptz),(10101,'2026-01-02T05:00:00Z'::timestamptz))v(n,starts);
insert into public.administrative_tasks(practice_id,id,location_id,kind,assignee_user_id,due_at,timezone,location_name,captured_location_version,state,created_by,updated_by,completed_by,completed_at)select pg_temp.practice(),pg_temp.id(10200+n),pg_temp.location(),'general_administration',pg_temp.id(case when n<2 then 1 else 3 end),'2026-01-01T12:00:00Z','America/New_York','Synthetic report clinic',1,(array['assigned','in_progress','completed','cancelled'])[n+1],pg_temp.id(1),pg_temp.id(1),case when n=2 then pg_temp.id(1)end,case when n=2 then '2026-01-01T14:00:00Z'::timestamptz end from generate_series(0,3)n;
set local role authenticated;select pg_temp.claim(1);
create function pg_temp.report(kind text default'appointments',page integer default 0)returns jsonb language sql as $$select public.doctor_operational_report(pg_temp.practice(),pg_temp.location(),'2026-01-01','2026-01-01',kind,page)$$;
-- Produce real synthetic persisted failure/preview/fulfillment records, then set only their run-owned historical created clocks.
select public.doctor_contact_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(10300),0,'create_contact','{"channel":"sms","destination":"+15550001234","recipient_kind":"patient","guardian_id":null}',pg_temp.id(10301));
select public.doctor_contact_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(10302),0,'grant_consent',jsonb_build_object('contact_id',pg_temp.id(10300),'contact_version',1,'purpose','appointment_reminder','source_ref','Synthetic report consent','source_day',(clock_timestamp()at time zone'America/New_York'-interval'1 minute')::date,'source_minute',extract(hour from clock_timestamp()at time zone'America/New_York'-interval'1 minute')::integer*60+extract(minute from clock_timestamp()at time zone'America/New_York'-interval'1 minute')::integer,'location_version',1),pg_temp.id(10303));
select public.doctor_outbox_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(10304),0,'enqueue',jsonb_build_object('intent',jsonb_build_object('contact_id',pg_temp.id(10300),'contact_version',1,'purpose','appointment_reminder','consent_version',1,'guardian_version',null),'expires_at',clock_timestamp()+interval'1 day','template','appointment_reminder_v1','parameters','{}'::jsonb),pg_temp.id(10305));
select public.doctor_contact_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(10302),1,'revoke_consent','{"source_ref":"Synthetic report withdrawal"}',pg_temp.id(10306));
select public.doctor_outbox_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(10304),1,'claim','{}',pg_temp.id(10307));
select public.doctor_import_command(pg_temp.practice(),pg_temp.location(),pg_temp.id(10400),0,'create',jsonb_build_object('mapping_version','patient-appointment-v1','synthetic',true,'source_ref','Synthetic report manifest','rows',jsonb_build_array(jsonb_build_object('source_id','R1','kind','patient','patient_source_id',null,'display_name','Synthetic report preview person','birth_date','2000-01-01','phone','','email','','starts_at',null,'state',null))),pg_temp.id(10401));
select public.doctor_import_command(pg_temp.practice(),pg_temp.location(),pg_temp.id(10400),1,'next','{"limit":50}',pg_temp.id(10402));
select public.doctor_import_command(pg_temp.practice(),pg_temp.location(),pg_temp.id(10400),2,'reconcile','{}',pg_temp.id(10403));
select pg_temp.command('create',jsonb_build_object('patient_id',pg_temp.patient(),'snapshot',jsonb_set(pg_temp.snapshot(),'{orders}',jsonb_build_array(jsonb_build_object('id',pg_temp.id(10500),'kind','lab','request','Synthetic report issued request','due_at',null,'state','requested','reason','')))),10501);
select pg_temp.command('start','{}',10502);select pg_temp.command('finalize','{}',10503);
select public.doctor_fulfillment_command(pg_temp.practice(),pg_temp.location(),pg_temp.patient(),pg_temp.id(10504),0,'create',jsonb_build_object('encounter_id',pg_temp.v('encounter')->>'encounter_id','source_version_id',pg_temp.detail()->'versions'->0->>'id','order_id',pg_temp.id(10500),'source_ref','Synthetic report tracking'),pg_temp.id(10505));
reset role;update public.message_outbox set created_at='2026-01-01T12:00:00Z'where id=pg_temp.id(10304);update public.synthetic_import_batches set created_at='2026-01-01T12:00:00Z'where id=pg_temp.id(10400);update public.operational_fulfillments set created_at='2026-01-01T12:00:00Z'where id=pg_temp.id(10504);set local role authenticated;
select is(pg_temp.report('messages')#>>'{totals,messages,failed}','1','actual consent-suppressed persisted message counted as failed');
select is(pg_temp.report('imports')#>>'{totals,imports,validated}','1','validated source preview counted independently of canonical work');
select is(pg_temp.report('fulfillment')#>>'{totals,fulfillment,requested}','1','issued operational request counted without clinical review');
select is(pg_temp.report()->>'total','40','C01: full appointment population excludes both outside local-day boundaries');
select is(jsonb_array_length(pg_temp.report()->'rows'),20,'first source page bounded');
select is(jsonb_array_length(pg_temp.report('appointments',1)->'rows'),20,'second page completes source population');
select is(pg_temp.report()->>'starts_at','2026-01-01T05:00:00+00:00','New York midnight uses explicit clinic timezone');
select is(pg_temp.report()->>'ends_at','2026-01-02T05:00:00+00:00','local end is half-open next midnight');
select is(pg_temp.report()#>>'{totals,appointments,completed}','7','completed count excludes cancelled and no-show sources');
select is(pg_temp.report()#>>'{totals,appointments,no_show}','6','no-show remains a distinct administrative state');
select is(pg_temp.report()#>>'{totals,follow_up,population}','4','follow-up population uses due instants');
select is(pg_temp.report()#>>'{totals,follow_up,completed}','1','task completion is independent of messages');
select is(pg_temp.report()#>>'{workload,0,open_count}','2','workload counts current open assignments only');
select is(pg_temp.report()->>'external_delivery','false','C03: report cannot claim external delivery');
select ok(pg_temp.report()::text not like'%Synthetic clinical patient%','report source projection contains no patient names');
reset role;
update public.appointments set starts_at='2026-01-03T12:00:00Z',ends_at='2026-01-03T12:05:00Z',version=version+1 where id=pg_temp.id(10000);
update public.administrative_tasks set assignee_user_id=pg_temp.id(3),version=version+1 where id=pg_temp.id(10200);
update public.memberships set capabilities=array['appointments.read']where id=pg_temp.id(201);update public.membership_locations set capabilities=array['appointments.read']where membership_id=pg_temp.id(201);
set local role authenticated;select pg_temp.claim(1);
select is(pg_temp.report()->>'total','39','C02: rescheduled source leaves the old window without a duplicate');
select is((select count(distinct x->>'id')from jsonb_array_elements((pg_temp.report()->'rows')||(pg_temp.report('appointments',1)->'rows'))x),39::bigint,'all pages reconcile unique source IDs');
select is(jsonb_array_length(pg_temp.report()->'workload'),2,'reassignment creates two current groups rather than double counting old owner');
select pg_temp.claim(3);
select is(pg_temp.report()->>'total','39','differently granted secretary sees authorized appointment totals');
select is(pg_temp.report()#>'{totals,follow_up}','null'::jsonb,'ungranted follow-up population is unavailable rather than fabricated zero');
select is(pg_temp.report('messages')->>'available','false','ungranted selected population visibly unavailable');
select is(pg_temp.report('messages')->'total','null'::jsonb,'unavailable messages never imply no failures');
select is(pg_temp.report('messages')->'rows','[]'::jsonb,'ungranted source identifiers not leaked');
select pg_temp.claim(2);
select throws_ok($$select pg_temp.report()$$,'42501','DOCTOR_ACCESS_DENIED','foreign doctor report denied');
select pg_temp.claim(1);
select is(extract(epoch from ((public.doctor_operational_report(pg_temp.practice(),pg_temp.location(),'2026-03-08','2026-03-08','appointments',0)->>'ends_at')::timestamptz-(public.doctor_operational_report(pg_temp.practice(),pg_temp.location(),'2026-03-08','2026-03-08','appointments',0)->>'starts_at')::timestamptz))/3600,23::numeric,'spring daylight-saving clinic day contains23 hours');
select is(extract(epoch from ((public.doctor_operational_report(pg_temp.practice(),pg_temp.location(),'2026-11-01','2026-11-01','appointments',0)->>'ends_at')::timestamptz-(public.doctor_operational_report(pg_temp.practice(),pg_temp.location(),'2026-11-01','2026-11-01','appointments',0)->>'starts_at')::timestamptz))/3600,25::numeric,'autumn daylight-saving clinic day contains25 hours');
select throws_ok($$select public.doctor_operational_report(pg_temp.practice(),pg_temp.location(),'2026-01-01','2027-01-01','appointments',0)$$,'22023','DOCTOR_REPORT_INVALID','unbounded reporting window denied');
reset role;set local role service_role;
select throws_ok($$select pg_temp.report()$$,'42501',null,'ambient service report execution denied');
select * from finish();rollback;
